// Applied rules: [III④, C3, III③]
// Skipped rules: [III②: Hit [3] is an interior `realloc` on `(*cell).e` whose ownership escapes this function via the hashmap field and is paired outside `hm_put`; alloc/free are not in the same function scope, so RAII conversion is out of scope.; II_vec: Hits [1,2] point at the search loop, but this function's loop trip count is data-dependent on `(*cell).c` and the main blocker is likely the opaque `strcmp` plus raw-pointer shape. Applying III④ and III③ first may moot the vectorization remarks; no standalone II_vec canonicalization targets a concrete remaining site here.]
#[inline]
unsafe fn hm_put(
    mut hm: *mut hashmap_t,
    mut key: *const c_char,
    mut value: *mut c_void,
) {
    let mut cell: *mut hashcell_t = (&raw mut (*hm).cell as *mut hashcell_t)
        .offset((hm_hash(key) & HASHMAP_CELLMASK as c_ulong) as isize);
    let count: size_t = (*cell).c;
    let entries_ptr: *mut hashentry_t = (*cell).e;
    let mut i: size_t = 0;
    i = 0 as size_t;
    while i < count {
        // SAFETY: `entries_ptr` is the bucket entry-array base, `count` is the stable
        // pre-realloc length for this search loop, `i < count` by the loop condition,
        // and no slice/reference aliases are created; this stays within the original
        // unchecked raw-pointer semantics.
        let entry: *mut hashentry_t = unsafe { entries_ptr.offset(i as isize) };
        if strcmp(key, (*entry).k) == 0 {
            (*entry).v = value;
            return;
        }
        i = i.wrapping_add(1);
    }
    (*cell).e = realloc(
        (*cell).e as *mut c_void,
        (::core::mem::size_of::<hashentry_t>() as size_t)
            .wrapping_mul(count.wrapping_add(1 as size_t)),
    ) as *mut hashentry_t;
    let append_idx: size_t = count;
    // SAFETY: `append_idx == count` is the first newly allocated slot after growing the
    // bucket storage to `count + 1` entries, matching the original append position.
    let entry: *mut hashentry_t = unsafe { (*cell).e.offset(append_idx as isize) };
    (*entry).k = strclone(key);
    (*entry).v = value;
    (*cell).c = count.wrapping_add(1);
}

